cat > /tmp/send_all_emails.py << 'ENDSCRIPT'
import json, subprocess

with open('/tmp/low_stock.json') as f:
    low_stock = json.load(f)

manager_email = 'laura_thompson@mcp.com'
sheet_url = 'https://docs.google.com/spreadsheets/d/sheet_0001/edit'

for item in low_stock:
    subject = f"[Stock Alert] {item['name']} Stock Below Safety Threshold"
    body = f"""Dear Purchasing Manager,

The system has detected that the following product's stock level is below the safety threshold. Please take immediate action:

Product Information
- Product Name: {item['name']}
- SKU: {item['sku']}
- Current Stock: {item['stock_quantity']}
- Safety Threshold: {item['threshold']}
- Supplier: {item['supplier_name']}
- Supplier Contact: {item['supplier_contact']}

Action Required
Please review the stock levels and consider placing a purchase order to replenish inventory.

For detailed information and to update the purchase requisition list, please visit the Google Sheets link: {sheet_url}

Best regards,
Stock Alert System"""

    args = json.dumps({
        'to': manager_email,
        'subject': subject,
        'body': body
    })
    cmd = f"mcp-tool call emails send_email '{args}'"
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    if 'Email sent successfully' in result.stdout:
        print(f"OK: {item['name']} - {item['sku']}")
    else:
        print(f"FAILED: {item['name']}")
        print(result.stdout)
        print(result.stderr)
ENDSCRIPT
